// The Go core's C API (generated by go build -buildmode=c-archive, see core/cmd/libtether).
#include "libtether.h"

// utun lookup in the extension. sys/kern_control.h is not in the iOS SDK; these match the kernel's
// definitions (as WireGuard's iOS client declares them too).
#include <sys/types.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#ifndef CTLIOCGINFO
#define CTLIOCGINFO 0xc0644e03UL
struct ctl_info {
    u_int32_t ctl_id;
    char ctl_name[96];
};
struct sockaddr_ctl {
    u_char sc_len;
    u_char sc_family;
    u_int16_t ss_sysaddr;
    u_int32_t sc_id;
    u_int32_t sc_unit;
    u_int32_t sc_reserved[5];
};
#endif
#ifndef AF_SYSTEM
#define AF_SYSTEM 32
#endif
